-- Animeko web-selector 规则集（转自 https://sub.creamycake.org/v1/css1.json）
-- 依据 2026-10-11 实测（关键词「火影忍者」）标注：
--   enabled=1 = 实测可达且解析出结果；enabled=0 = 被墙/403/超时/解析0，需后续排查
-- 这些源返回「播放页 URL」，取直链需无头浏览器（browser_resolve=1）
-- 导入后建议调用 POST /api/source/test/all 复测，再按结果调整 enabled
USE abc_anime;
ON DUPLICATE KEY UPDATE base_url=VALUES(base_url), css_config=VALUES(css_config), enabled=VALUES(enabled), updated_at=NOW();
